async function ensureSeeded(pool: ReturnType<typeof getPool>): Promise<void> {
  const { rows } = await pool.query<{ count: string }>('SELECT COUNT(*)::text AS count FROM research_report_types');
  if (Number(rows[0].count) > 0) return;

  for (const r of SEED_REPORT_TYPES) {
    await pool.query(
      `INSERT INTO research_report_types (category, subcategory, report_name, description, typical_inputs, typical_outputs, methodology, ai_generatable, complexity, estimated_pages)
       VALUES ($1,$2,$3,$4,$5,$6,$7,TRUE,$8,$9)`,
      [r.category, r.subcategory, r.report_name, r.description, r.typical_inputs, r.typical_outputs, r.methodology, r.complexity, r.estimated_pages]
    );
  }
}

export async function GET(req: NextRequest) {
  const denied = await requireAdmin(req);
  if (denied) return denied;
  if (!databaseConfigured()) return Response.json({ error: 'DATABASE_URL is not configured.' }, { status: 503 });

  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query(`
      CREATE TABLE IF NOT EXISTS research_report_types (
        id SERIAL PRIMARY KEY, category TEXT, subcategory TEXT, report_name TEXT,
        description TEXT, typical_inputs TEXT[], typical_outputs TEXT[],
        methodology TEXT, ai_generatable BOOLEAN DEFAULT TRUE,
        complexity TEXT DEFAULT 'medium', estimated_pages INTEGER DEFAULT 10,
        created_at TIMESTAMPTZ DEFAULT NOW()
      );
      CREATE TABLE IF NOT EXISTS research_reports_generated (
        id SERIAL PRIMARY KEY, report_type_id INTEGER REFERENCES research_report_types(id),
        title TEXT, input_params JSONB, report_content TEXT, status TEXT DEFAULT 'draft',
        word_count INTEGER DEFAULT 0, created_by TEXT DEFAULT 'admin',
        created_at TIMESTAMPTZ DEFAULT NOW()
      );
    `);
    await ensureSeeded(pool);

    const { searchParams } = new URL(req.url);
    const category = searchParams.get('category');
    const complexity = searchParams.get('complexity');
    const search = searchParams.get('search');

    const conditions: string[] = [];
    const params: unknown[] = [];
    let idx = 1;

    if (category) { conditions.push(`category = $${idx++}`); params.push(category); }
    if (complexity) { conditions.push(`complexity = $${idx++}`); params.push(complexity); }
    if (search) { conditions.push(`(report_name ILIKE $${idx} OR description ILIKE $${idx})`); params.push(`%${search}%`); idx++; }

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const types = await client.query<{
      id: string; category: string; subcategory: string; report_name: string;
      description: string; typical_inputs: string[]; typical_outputs: string[];
      methodology: string; ai_generatable: boolean; complexity: string; estimated_pages: string;
    }>(`SELECT * FROM research_report_types ${where} ORDER BY category, report_name`, params);

    const statsRows = await client.query<{ total_types: string; total_categories: string; total_generated: string }>(`
      SELECT
        (SELECT COUNT(*)::text FROM research_report_types) AS total_types,
        (SELECT COUNT(DISTINCT category)::text FROM research_report_types) AS total_categories,
        (SELECT COUNT(*)::text FROM research_reports_generated) AS total_generated
    `);
    const stats = statsRows.rows[0];

    return Response.json({
      reportTypes: types.rows.map(r => ({
        id: Number(r.id), category: r.category, subcategory: r.subcategory,
        reportName: r.report_name, description: r.description,
        typicalInputs: r.typical_inputs, typicalOutputs: r.typical_outputs,
        methodology: r.methodology, aiGeneratable: r.ai_generatable,
        complexity: r.complexity, estimatedPages: Number(r.estimated_pages),
      })),
      stats: {
        totalTypes: Number(stats.total_types),
        totalCategories: Number(stats.total_categories),
        totalGenerated: Number(stats.total_generated),
      },
    });
  } finally {
    client.release();
  }
}
